    <node TEXT="2.2 题材的生命周期" POSITION="right">
      <node TEXT="特征：政策出台或重大事件发生" />
      <node TEXT="操作：关注首批涨停股" />
      <node TEXT="风险：不确定性高" />
      <node TEXT="特征：板块内个股开始联动" />
      <node TEXT="操作：买入龙头股" />
    </node>
    <node TEXT="2.3 如何判断题材的级别？" POSITION="right">
      <node TEXT="政策级别高" />
      <node TEXT="影响范围广" />
      <node TEXT="炒作周期长（通常1-3个月）" />
      <node TEXT="政策支持" />
      <node TEXT="产业发展趋势" />
