  <node TEXT="第三章：短线选股要诀" POSITION="right">
  </node>
    <node TEXT="3.1 选股的核心原则" POSITION="right">
      <node TEXT="1. **强势原则**：只做强势股，不做弱势股
2. **龙头原则**：只做龙头，不做跟风
3. **题材原则**：紧跟市场主流题材" />
    </node>
    <node TEXT="3.2 选股的具体标准" POSITION="right">
      <node TEXT="涨停板启动" />
      <node TEXT="成交量放大" />
      <node TEXT="突破关键阻力位" />
      <node TEXT="属于当前市场最热题材" />
      <node TEXT="有政策或重大利好支持" />
    </node>
    <node TEXT="3.3 选股的实战技巧" POSITION="right">
      <node TEXT="每天关注涨幅榜前50名" />
      <node TEXT="找出属于同一板块的个股" />
      <node TEXT="判断是否为题材启动" />
      <node TEXT="每天关注涨停板数量" />
      <node TEXT="找出涨停板最多的板块" />
    </node>
  <node TEXT="第四章：连板战法（上）" POSITION="right">
  </node>
    <node TEXT="4.1 连板股的定义" POSITION="right">
      <node TEXT="**连板股**：连续涨停的股票" />
      <node TEXT="**启动板**：第一个涨停板" />
      <node TEXT="**加速板**：后续的涨停板" />
      <node TEXT="**分歧板**：出现分歧的涨停板" />
    </node>
    <node TEXT="4.2 连板股的操作时机" POSITION="right">
      <node TEXT="特征：题材刚启动，市场关注度不高" />
      <node TEXT="操作：可以追涨，但要控制仓位" />
      <node TEXT="风险：可能是假突破" />
      <node TEXT="特征：题材发酵，市场关注度提高" />
      <node TEXT="操作：大胆买入，享受主升浪" />
    </node>
    <node TEXT="4.3 连板股的买入技巧" POSITION="right">
      <node TEXT="在涨停板价位买入" />
      <node TEXT="需要快速反应和果断决策" />
      <node TEXT="风险：可能买在最高点" />
      <node TEXT="在盘中回调时买入" />
      <node TEXT="需要精准判断支撑位" />
    </node>
  <node TEXT="第五章：连板战法（下）" POSITION="right">
  </node>
    <node TEXT="5.1 连板股的卖出技巧" POSITION="right">
      <node TEXT="特征：涨停板被打开" />
      <node TEXT="操作：立即卖出" />
      <node TEXT="原因：多头力量衰竭" />
      <node TEXT="特征：成交量异常放大" />
      <node TEXT="操作：分批卖出" />
    </node>
    <node TEXT="5.2 连板股的风险控制" POSITION="right">
      <node TEXT="单只连板股不超过3成仓" />
      <node TEXT="总仓位不超过7成仓" />
      <node TEXT="保留3成机动资金" />
      <node TEXT="跌破止损线（-5%到-8%）立即止损" />
      <node TEXT="走势不符合预期立即止损" />
    </node>
    <node TEXT="5.3 连板战法的常见误区" POSITION="right">
      <node TEXT="表现：不考虑位置，盲目追涨停板" />
      <node TEXT="危害：容易买在最高点" />
      <node TEXT="纠正：只在合适的时机买入" />
      <node TEXT="表现：跌破止损线不止损" />
      <node TEXT="危害：小亏变大亏" />
    </node>
